class Example {
    void method() {
        String path = "/a/b/c/";
        int index = path.lastIndexOf("/");
        System.out.println(index);
    }
}

afterExample:
class Example {
    void method() {
        String path = "/a/b/c/";
        int index = path.lastIndexOf('/');
        System.out.println(index);
    }
}

negativeExample:
class Example {
    void method() {
        String path = "/a/b/c/";
        // Does not match: different literal
        int index1 = path.lastIndexOf("abc");
